 280	// ── daemon supervision ───────────────────────────────────────────────────
 281	//
 282	// The Tauri shell owns the ocean-daemon lifecycle when nothing else is
 283	// serving on `OCEAN_DAEMON_URL` (default 127.0.0.1:4780, mirroring the
 284	// daemon's own `OCEAN_BIND`). Supervision is EXPLICIT in v1 — there is no
 285	// auto-spawn at boot; the user starts/restarts from the palette or the tray,
 286	// and a background poller reports liveness to the webview as `daemon-status`
 287	// events (emitted on change only).
 288	//
 289	// `ocean-daemon` is the binary in ocean-os/crates/ocean-daemon
 290	// (`[[bin]] name = "ocean-daemon"`), served via `axum::serve` over a
 291	// TcpListener — so a raw TCP connect to host:port is a sufficient liveness
 292	// probe without pulling in reqwest.
 293	
 294	/// Liveness probe timeout. The daemon binds its port within tens of ms of
 295	/// boot, so half a second is ample and keeps the poller (and the explicit
 296	/// start-check) from stalling.
 297	const DAEMON_PROBE_TIMEOUT: Duration = Duration::from_millis(500);
 298	/// Poll interval for the background liveness poller.
 299	const DAEMON_POLL_INTERVAL: Duration = Duration::from_secs(5);
 300	/// Default daemon URL — matches the wasm surface's `DEFAULT_DAEMON_URL` and
 301	/// the daemon's `OCEAN_BIND` default (`127.0.0.1:4780`). Reading
 302	/// `OCEAN_DAEMON_URL` keeps the shell and the wasm bundle pointed at one
 303	/// configurable origin.
 304	const DEFAULT_DAEMON_URL: &str = "http://127.0.0.1:4780";
 305	
 306	/// Liveness state of the supervised daemon, reported to the webview. Wire
 307	/// discriminants are lowercase via `rename_all` — `running` | `stopped` |
 308	/// `starting` | `unreachable`.
 309	#[derive(Clone, Copy, PartialEq, Eq, Debug, Serialize)]
 310	#[serde(rename_all = "lowercase")]
 311	enum DaemonState {
 312	    /// Port reachable. `pid` is present iff the shell owns the child.
 313	    Running,
 314	    /// No child and the port is not reachable (never started / just stopped).
 315	    Stopped,
 316	    /// The shell owns a live child but the port is not up yet (just spawned).
 317	    Starting,
 318	    /// Port not reachable after previously being up, with no owned child —
 319	    /// an external daemon that went away.
 320	    Unreachable,
 321	}
 322	
 323	impl Default for DaemonState {
 324	    fn default() -> Self {
 325	        DaemonState::Stopped
 326	    }
 327	}
