 329	/// Pure state decision (unit-tested, no I/O). Maps the raw signals — port
 330	/// reachable, owned child alive, port ever reached — to the reported state.
 331	fn decide_daemon_state(reachable: bool, child_alive: bool, reachable_ever: bool) -> DaemonState {
 332	    match (reachable, child_alive) {
 333	        (true, _) => DaemonState::Running,
 334	        (false, true) => DaemonState::Starting,
 335	        (false, false) => {
 336	            if reachable_ever {
 337	                DaemonState::Unreachable
 338	            } else {
 339	                DaemonState::Stopped
 340	            }
