 682	fn repo_status_counts(repo: &Repository) -> (usize, usize) {
 683	    let mut opts = git2::StatusOptions::new();
 684	    opts.include_untracked(true);
 685	
 686	    let statuses = match repo.statuses(Some(&mut opts)) {
 687	        Ok(s) => s,
 688	        Err(_) => return (0, 0),
 689	    };
 690	
 691	    let index_mask = git2::Status::INDEX_NEW
 692	        | git2::Status::INDEX_MODIFIED
 693	        | git2::Status::INDEX_DELETED
 694	        | git2::Status::INDEX_RENAMED
 695	        | git2::Status::INDEX_TYPECHANGE;
 696	
 697	    let wt_mask = git2::Status::WT_NEW
 698	        | git2::Status::WT_MODIFIED
 699	        | git2::Status::WT_DELETED
 700	        | git2::Status::WT_RENAMED
 701	        | git2::Status::WT_TYPECHANGE;
 702	
 703	    let mut dirty = 0usize;
 704	    let mut staged = 0usize;
 705	
 706	    for entry in statuses.iter() {
 707	        let s = entry.status();
 708	        if s.intersects(index_mask) {
 709	            staged += 1;
 710	        }
 711	        if s.intersects(wt_mask) {
 712	            dirty += 1;
 713	        }
 714	    }
 715	
 716	    (dirty, staged)
 717	}
