 719	fn repo_recent_commits(repo: &Repository, n: usize) -> Vec<CommitInfoDto> {
 720	    let head_commit = match repo
 721	        .head()
 722	        .ok()
 723	        .and_then(|h| h.target())
 724	        .and_then(|oid| repo.find_commit(oid).ok())
 725	    {
 726	        Some(c) => c,
 727	        None => return vec![],
 728	    };
 729	
 730	    let mut walk = match repo.revwalk() {
 731	        Ok(w) => w,
 732	        Err(_) => return vec![],
 733	    };
 734	    walk.set_sorting(git2::Sort::TIME).ok();
 735	    if walk.push(head_commit.id()).is_err() {
 736	        return vec![];
 737	    }
 738	
 739	    let mut commits = Vec::with_capacity(n);
 740	    for oid in walk.flatten() {
 741	        let commit = match repo.find_commit(oid) {
 742	            Ok(c) => c,
 743	            Err(_) => continue,
 744	        };
 745	        let id_short = format!("{}", &oid.to_string()[..7.min(oid.to_string().len())]);
 746	        let summary = commit.summary().unwrap_or("").to_string();
 747	        let author = commit.author().name().unwrap_or("").to_string();
 748	        let when_epoch = commit.time().seconds();
 749	
 750	        commits.push(CommitInfoDto {
 751	            id_short,
 752	            summary,
 753	            author,
 754	            when_epoch,
 755	        });
 756	
 757	        if commits.len() >= n {
 758	            break;
 759	        }
 760	    }
 761	
 762	    commits
 763	}
