 306	/// Liveness state of the supervised daemon, reported to the webview. Wire
 307	/// discriminants are lowercase via `rename_all` — `running` | `stopped` |
 308	/// `starting` | `unreachable`.
 309	#[derive(Clone, Copy, PartialEq, Eq, Debug, Serialize)]
 310	#[serde(rename_all = "lowercase")]
 311	enum DaemonState {
 312	    /// Port reachable. `pid` is present iff the shell owns the child.
 313	    Running,
 314	    /// No child and the port is not reachable (never started / just stopped).
 315	    Stopped,
 316	    /// The shell owns a live child but the port is not up yet (just spawned).
 317	    Starting,
 318	    /// Port not reachable after previously being up, with no owned child —
 319	    /// an external daemon that went away.
 320	    Unreachable,
 321	}
 322	
 323	impl Default for DaemonState {
 324	    fn default() -> Self {
 325	        DaemonState::Stopped
 326	    }
 327	}
 328	
 329	/// Pure state decision (unit-tested, no I/O). Maps the raw signals — port
 330	/// reachable, owned child alive, port ever reached — to the reported state.
 331	fn decide_daemon_state(reachable: bool, child_alive: bool, reachable_ever: bool) -> DaemonState {
 332	    match (reachable, child_alive) {
 333	        (true, _) => DaemonState::Running,
 334	        (false, true) => DaemonState::Starting,
 335	        (false, false) => {
 336	            if reachable_ever {
 337	                DaemonState::Unreachable
 338	            } else {
 339	                DaemonState::Stopped
 340	            }
 650	    let head = match repo.head() {
 651	        Ok(h) if h.is_branch() => h,
 652	        _ => return (0, 0),
 653	    };
 654	    let branch_name = match head.shorthand() {
 655	        Some(n) => n,
 656	        None => return (0, 0),
 657	    };
 658	    let branch = match repo.find_branch(branch_name, git2::BranchType::Local) {
 659	        Ok(b) => b,
 660	        Err(_) => return (0, 0),
 661	    };
 662	    let upstream = match branch.upstream() {
 663	        Ok(up) => up,
 664	        Err(_) => return (0, 0),
 665	    };
 666	
 667	    let local_oid = match branch.get().target() {
 668	        Some(oid) => oid,
 669	        None => return (0, 0),
 670	    };
 671	    let upstream_oid = match upstream.get().target() {
 672	        Some(oid) => oid,
 673	        None => return (0, 0),
 674	    };
 675	
 676	    match repo.graph_ahead_behind(local_oid, upstream_oid) {
 677	        Ok((a, b)) => (a as usize, b as usize),
 678	        Err(_) => (0, 0),
 679	    }
 680	}
