+/// Group + filter sessions for the shared panel display: project-first, newest
+/// sessions first, "Other" last. Historical zero-turn drafts remain hidden
+/// unless active, preserving browser/extension behavior; the Tauri Island owns
+/// its separate bounded catalogue and keeps zero-turn discoverability there.
+/// Pure — no WASM, testable with `cargo test`.
 pub(crate) fn group_for_panel(
     sessions: &[SessionSummary],
     projects: &[ProjectInfo],
     active_id: Option<&str>,
 ) -> Vec<ProjectSection> {
